effect.shader:
float curva(float x) {
    float bk = blackLift;
    float wh = 1.0 + whiteHold;
    float y = (x - bk) / max(wh - bk, 1e-4);
    y = clamp(y, 0.0, 1.0);
    // Deslocamento dos médios em torno de 0.5
    y = pow(y, 1.0 - midShift);
    // Contraste em torno de 0.5
    y = clamp((y - 0.5) * contrast + 0.5, 0.0, 1.0);
    return y;
}

void main() {
    vec4 c = texture(inputImg, acScreenNorm);
    fragColor = vec4(curva(c.r), curva(c.g), curva(c.b), c.a);
}
